/** The pools on a sheet and their members. */
@Service
public class PoolService {

    /** The most a member's share can be, and what a balanced pool's shares total. */
    public static final BigDecimal FULL = new BigDecimal("100.00");

    /** A member of a pool as it stands: the person, their share, and whether they are retired. */
    public record Member(Person person, BigDecimal share) {

        /** What the share counts toward the pool's total: nothing once the person is retired, whatever the date. */
        public BigDecimal counted() {
            return person.isRetired() ? BigDecimal.ZERO.setScale(2) : share;
        }
    }

    /** A pool with its members, in the order they were added, and the sheet's pot (null: none). */
    public record PoolWithMembers(Pool pool, List<Member> members, BigDecimal pot) {

        /** The members' shares added up, a retired member's counting as 0.00. */
        public BigDecimal totalShare() {
            return members.stream().map(Member::counted).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        }

        /** Balanced when the shares total exactly 100.00. */
        public boolean balanced() {
            return totalShare().compareTo(FULL) == 0;
        }

        /** Each member's cut of the pot, in the order of the members; none (null) when there is no pot or the pool
         *  is not balanced. A cut is the pot times the share over 100, rounded half to even to two decimals, 0.00 for
         *  a retired member; what the cuts fall short of (or over) the pot goes to the member with the largest share
         *  counted, the earliest added on a tie, so the cuts total exactly the pot. */
        public List<BigDecimal> cuts() {
            if (pot == null || !balanced()) {
                return null;
            }
            List<BigDecimal> cuts = new ArrayList<>(members.stream()
                    .map(m -> pot.multiply(m.counted()).divide(FULL, 2, RoundingMode.HALF_EVEN)).toList());
            BigDecimal remainder = pot.subtract(cuts.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add));
            int largest = 0;
            for (int i = 1; i < members.size(); i++) {
                if (members.get(i).counted().compareTo(members.get(largest).counted()) > 0) {
                    largest = i;
                }
            }
            cuts.set(largest, cuts.get(largest).add(remainder));
            return cuts;
        }
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            SheetService sheets, SheetRepository sheetStore, Audit audit) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
    }

    /** The sheet's pools, in the order they were added, each with its members. */
    @Transactional(readOnly = true)
    public List<PoolWithMembers> list(String sheetId) {
        List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId);
        BigDecimal pot = sheetStore.findById(sheetId).map(Sheet::getPot).orElse(null);
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList())
                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
        return list.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()).stream()
                .filter(m -> byId.containsKey(m.getPersonId()))
                .map(m -> new Member(byId.get(m.getPersonId()), m.getShare())).toList(), pot)).toList();
    }

    /** Add a pool by its name, trimmed; refused when blank or already a pool on the sheet. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        String key = name == null ? "" : name.strip();
        if (key.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A pool has a name");
        }
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        if (pools.existsBySheetIdAndName(sheetId, key)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet");
        }
        Pool saved;
        try {
            saved = pools.saveAndFlush(new Pool(sheetId, key));
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet");
        }
        audit.recordChangeOnCommit(sheetId, user, "POOL_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName());
        return saved;
    }

    /** Add a person of the sheet to the pool with a share percent; refused when the person is already in it,
     *  or the share is not more than 0.00 and at most 100.00 with up to two decimals. */
    @Transactional
    public PoolWithMembers addMember(String sheetId, String user, long poolId, long personId, BigDecimal share) {
        if (share == null || share.signum() <= 0 || share.compareTo(FULL) > 0
                || share.stripTrailingZeros().scale() > 2) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A share is more than 0.00 and at most 100.00, with up to two decimals");
        }
        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Pool pool = pools.findById(poolId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool on this sheet"));
        Person person = people.findById(personId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (members.existsByPoolIdAndPersonId(pool.getId(), personId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool");
        }
        try {
            members.saveAndFlush(new PoolMember(pool.getId(), personId, scaled));
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool");
        }
        audit.recordChangeOnCommit(sheetId, user, "POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user
                + " pool=" + pool.getName() + " name=" + person.getName() + " share=" + scaled.toPlainString());
        return list(sheetId).stream().filter(p -> p.pool().getId().equals(pool.getId())).findFirst().orElseThrow();
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** A share percent the pool's row accepts: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A member of a pool: a person of the sheet with their share percent. */
export interface PoolMemberView {
  personId: number;
  name: string;
  share: string;
  /** Retired as soon as a retirement date is set: their share then counts as 0.00 toward the total. */
  retired: boolean;
  /** Their cut of the sheet's pot (two decimals); null when there is no pot or the pool is not balanced. */
  cut: string | null;
}

/** A pool on the sheet: its members, their total share, and balanced when that is exactly 100.00. */
export interface PoolView {
  id: number;
  name: string;
  members: PoolMemberView[];
  totalShare: string;
  balanced: boolean;
}

// The pools on the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly list = signal<PoolView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's pools from the store; null clears them. */
  load(sheetId: string | null): Observable<PoolView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<PoolView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Add a pool; refused when the name is blank or already a pool on the sheet. */
  add(sheetId: string, name: string): Observable<PoolView> {
    return this.http.post<PoolView>(this.base(sheetId), { name }).pipe(
      tap((added) => this.list.update((list) => [...list, added])),
    );
  }

  /** Add a person to a pool with a share; refused when they are already in it or the share is out of range. */
  addMember(sheetId: string, poolId: number, personId: number, share: string): Observable<PoolView> {
    return this.http.post<PoolView>(`${this.base(sheetId)}/${poolId}/members`, { personId, share }).pipe(
      tap((saved) => this.list.update((list) => list.map((p) => (p.id === saved.id ? saved : p)))),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }
}
import { Component, computed, inject, input, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { EMPTY, distinctUntilChanged, skip, switchMap } from 'rxjs';
import { PersonView } from '../../core/people';
import { Pools, SHARE_PATTERN } from '../../core/pools';
import { Sheets } from '../../core/sheet';

type MemberForm = FormGroup<{ personId: FormControl<string>; share: FormControl<string> }>;

// The sheet's pools: each has members chosen from the sheet's people, with a share percent of it.
@Component({
  selector: 'app-pools',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="pools-heading">
      <h3 id="pools-heading">Pools</h3>
      <ul aria-label="Pools">
        @for (pool of pools.all(); track pool.id) {
          <li [attr.data-testid]="'pool-row-' + pool.name">
            <span data-testid="pool-name">{{ pool.name }}</span>:
            total share <span data-testid="pool-total-share">{{ pool.totalShare }}</span>,
            balanced <span data-testid="pool-balanced">{{ pool.balanced ? 'yes' : 'no' }}</span>
            <ul [attr.aria-label]="'Members of ' + pool.name">
              @for (m of pool.members; track m.personId) {
                <li [attr.data-testid]="'pool-member-' + pool.name + '-' + m.personId">
                  <span data-testid="pool-member-name">{{ m.name }}</span>:
                  <span data-testid="pool-share">{{ m.share }}</span>,
                  cut <span data-testid="pool-cut">{{ m.cut ?? '' }}</span>
                  @if (m.retired) { (retired) }
                </li>
              }
            </ul>
            <form [formGroup]="memberForm(pool.id)" (ngSubmit)="addMember(pool.id)"
                  [attr.aria-label]="'Add a member to ' + pool.name">
              <label [attr.for]="'pool-member-select-' + pool.id">Person</label>
              <select [id]="'pool-member-select-' + pool.id" data-testid="pool-member-select" formControlName="personId">
                <option value="">Choose a person</option>
                @for (p of people(); track p.id) {
                  <option [value]="p.id">{{ p.name }}</option>
                }
              </select>
              <label [attr.for]="'pool-member-share-' + pool.id">Share %</label>
              <input [id]="'pool-member-share-' + pool.id" data-testid="pool-member-share" formControlName="share"
                     inputmode="decimal" autocomplete="off" />
              <button type="submit" data-testid="pool-member-add" [disabled]="busy().has(pool.id)">Add member</button>
              @if (errors().get(pool.id); as err) {
                <p role="alert" data-testid="pool-error">{{ err }}</p>
              }
            </form>
          </li>
        }
      </ul>

      <form [formGroup]="form" (ngSubmit)="add()" aria-label="Add a pool">
        <label for="pool-form-name">Name</label>
        <input id="pool-form-name" data-testid="pool-form-name" formControlName="name" autocomplete="off" />
        <button type="submit" data-testid="pool-form-submit" [disabled]="saving()">Add pool</button>
        @if (error(); as err) {
          <p role="alert" data-testid="pool-form-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class PoolsPanel {
  /** The sheet's people, the members are chosen from. */
  readonly people = input.required<PersonView[]>();

  protected readonly pools = inject(Pools);
  private readonly sheets = inject(Sheets);

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** Each pool's error, by pool id. */
  protected readonly errors = signal<ReadonlyMap<number, string>>(new Map());
  /** The pools a member is being added to. */
  protected readonly busy = signal<ReadonlySet<number>>(new Set());
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });
  private readonly memberForms = new Map<number, MemberForm>();

  constructor() {
    // Each (re)load of a sheet re-reads its pools from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          this.errors.set(new Map());
          this.memberForms.clear();
          return this.pools.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the pools.') });
    // A change of the sheet's pot re-reads the pools, with their cuts of it.
    toObservable(computed(() => {
      const sheet = this.sheets.current();
      return sheet ? `${sheet.id}\n${sheet.pot ?? ''}` : null;
    }))
      .pipe(
        distinctUntilChanged(),
        skip(1),
        switchMap(() => {
          const sheet = this.sheets.current();
          return sheet && sheet.id === this.sheets.loaded()?.id ? this.pools.load(sheet.id) ?? EMPTY : EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the pools.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  /** The pool row's form to add a member, made the first time the row shows. */
  protected memberForm(poolId: number): MemberForm {
    let form = this.memberForms.get(poolId);
    if (!form) {
      const made: MemberForm = new FormGroup({
        personId: new FormControl('', { nonNullable: true }),
        share: new FormControl('', { nonNullable: true }),
      });
      made.valueChanges.subscribe(() => this.setError(poolId, null));
      this.memberForms.set(poolId, made);
      form = made;
    }
    return form;
  }

  protected add(): void {
    // A second submit before the first has answered is ignored, so it records one pool.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const name = this.form.controls.name.value.trim();
    if (name === '') {
      this.error.set('Type the pool\'s name.');
      return;
    }
    this.saving.set(true);
    this.pools.add(sheet.id, name).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ name: '' }, { emitEvent: false });
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Could not add that pool: is it already on the sheet?');
      },
    });
  }

  protected addMember(poolId: number): void {
    if (this.busy().has(poolId)) return;
    this.setError(poolId, null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const value = this.memberForm(poolId).getRawValue();
    const share = value.share.trim();
    if (value.personId === '') {
      this.setError(poolId, 'Choose a person to add.');
      return;
    }
    if (!SHARE_PATTERN.test(share) || Number(share) <= 0 || Number(share) > 100) {
      this.setError(poolId, 'Type a share more than 0.00 and at most 100.00, with up to two decimals.');
      return;
    }
    this.busy.update((s) => new Set(s).add(poolId));
    const done = () => this.busy.update((s) => {
      const next = new Set(s);
      next.delete(poolId);
      return next;
    });
    this.pools.addMember(sheet.id, poolId, Number(value.personId), share).subscribe({
      next: () => {
        done();
        this.memberForm(poolId).reset({ personId: '', share: '' }, { emitEvent: false });
      },
      error: () => {
        done();
        this.setError(poolId, 'Could not add that member: are they already in the pool?');
      },
    });
  }

  private setError(poolId: number, message: string | null): void {
    this.errors.update((m) => {
      const next = new Map(m);
      if (message === null) next.delete(poolId);
      else next.set(poolId, message);
      return next;
    });
  }
}
